mapper.insert:
INSERT INTO t_knowledge_version(knowledge_base_id,object_type,object_code,version_no,title,summary,content,status,confidence,change_type,changed_by,supersedes_version_no)
SELECT #{kb},#{objectType},#{objectCode},COALESCE(v.max_version,0)+1,o.title,o.summary,o.content,o.status,o.confidence,#{changeType},#{changedBy},NULLIF(v.max_version,0)
FROM (
 SELECT k.title,k.summary,k.content,k.status,k.confidence FROM t_knowledge_card k
 WHERE #{objectType}='CARD' AND k.knowledge_base_id=#{kb} AND k.knowledge_code=#{objectCode}
 UNION ALL
 SELECT c.subject,c.predicate,c.object_value,c.status,c.confidence FROM t_claim c
 WHERE #{objectType}='CLAIM' AND c.knowledge_base_id=#{kb} AND c.claim_code=#{objectCode}
) o CROSS JOIN (SELECT COALESCE(MAX(version_no),0) max_version FROM t_knowledge_version WHERE object_type=#{objectType} AND object_code=#{objectCode}) v

mapper.select:
SELECT * FROM t_index_outbox WHERE knowledge_base_id=#{kb}
AND status=#{status}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT d.id documentId,s.id sourceId,s.knowledge_base_id knowledgeBaseId,s.name sourceName,s.source_uri sourceUri,s.authority_score authorityScore
FROM t_document d JOIN t_source_version sv ON sv.id=d.source_version_id JOIN t_source s ON s.id=sv.source_id
WHERE d.id=#{documentId}

mapper.insert:
INSERT IGNORE INTO t_index_outbox_archive(id,event_id,idempotency_key,knowledge_base_id,aggregate_type,aggregate_key,event_type,object_version,target_path,payload_json,status,attempt_count,max_attempts,result_json,last_error,created_time,processed_time)
SELECT id,event_id,idempotency_key,knowledge_base_id,aggregate_type,aggregate_key,event_type,object_version,target_path,payload_json,status,attempt_count,max_attempts,result_json,last_error,created_time,processed_time
FROM t_index_outbox WHERE status IN ('SUCCEEDED','SKIPPED') AND processed_time<#{cutoff} ORDER BY id LIMIT #{limit}

INSERT IGNORE INTO t_index_delivery_attempt_archive(id,event_id,attempt_no,status,duration_ms,response_json,error_text,created_time)
SELECT a.id,a.event_id,a.attempt_no,a.status,a.duration_ms,a.response_json,a.error_text,a.created_time
FROM t_index_delivery_attempt a JOIN t_index_outbox_archive o ON o.event_id=a.event_id WHERE o.processed_time<#{cutoff}

mapper.update:
UPDATE t_index_schema_release SET snapshot_checksum=#{snapshotChecksum},
source_high_watermark=#{sourceHighWatermark},source_end_watermark=#{sourceEndWatermark},
snapshot_count=#{snapshotCount},integrity_state=#{integrityState}
WHERE release_id=#{releaseId}

mapper.select:
SELECT query_id queryId,original_query originalQuery,answer,model_name modelName,
       latency_ms latencyMs,error_code errorCode,created_time createdTime
FROM t_query_trace
WHERE knowledge_base_id=#{kb}
ORDER BY created_time DESC
LIMIT #{limit}

SELECT claim_code claimCode,subject,predicate,object_value objectValue,status,valid_from validFrom,valid_to validTo,version,confidence
FROM t_claim WHERE knowledge_base_id=#{kb} AND valid_to IS NOT NULL AND valid_to >= NOW() AND valid_to <= #{horizon}
AND (status IS NULL OR status NOT IN ('EXPIRED','SUPERSEDED','REJECTED')) ORDER BY valid_to

SELECT 'CARD' objectType,kc.knowledge_code objectCode,'EVIDENCE_LINK' impactType,kc.status status FROM t_knowledge_evidence ke JOIN t_knowledge_card kc ON kc.knowledge_code=ke.knowledge_code JOIN t_evidence e ON e.id=ke.evidence_id WHERE e.source_id=#{sourceId}
UNION ALL
SELECT 'CLAIM',c.claim_code,'EVIDENCE_LINK',c.status FROM t_claim_evidence ce JOIN t_claim c ON c.claim_code=ce.claim_code JOIN t_evidence e ON e.id=ce.evidence_id WHERE e.source_id=#{sourceId}
UNION ALL
SELECT 'ENTITY',e.entity_code,'GRAPH_NODE',e.status FROM t_entity e WHERE e.source_id=#{sourceId}

SELECT 'CARD' nodeType,kc.knowledge_code code,kc.title title,kc.status status FROM t_knowledge_card kc WHERE kc.knowledge_base_id=#{kb} AND kc.knowledge_code=#{code}
UNION ALL SELECT 'CLAIM',c.claim_code,CONCAT_WS(' ',c.subject,c.predicate,c.object_value),c.status FROM t_claim c WHERE c.knowledge_base_id=#{kb} AND c.claim_code=#{code}
UNION ALL SELECT 'EVIDENCE',e.evidence_code,LEFT(COALESCE(e.quote_text,''),80),e.status FROM t_evidence e WHERE e.knowledge_base_id=#{kb} AND e.evidence_code=#{code}
UNION ALL SELECT 'ENTITY',en.entity_code,en.canonical_name,en.status FROM t_entity en WHERE en.knowledge_base_id=#{kb} AND en.entity_code=#{code}
UNION ALL SELECT 'SOURCE',s.source_code,s.name,s.status FROM t_source s WHERE s.knowledge_base_id=#{kb} AND s.source_code=#{code}
LIMIT 1

SELECT ke.knowledge_code sourceCode,e.evidence_code targetCode,'SUPPORTED_BY' edgeType,COALESCE(ke.support_type,'SUPPORT') semanticType,ke.support_score confidence
FROM t_knowledge_evidence ke JOIN t_evidence e ON e.id=ke.evidence_id JOIN t_knowledge_card kc ON kc.knowledge_code=ke.knowledge_code
WHERE e.knowledge_base_id=#{kb}

SELECT ce.claim_code sourceCode,e.evidence_code targetCode,'SUPPORTED_BY' edgeType,COALESCE(ce.support_type,'SUPPORT') semanticType,ce.support_score confidence
FROM t_claim_evidence ce JOIN t_evidence e ON e.id=ce.evidence_id JOIN t_claim c ON c.claim_code=ce.claim_code
WHERE e.knowledge_base_id=#{kb}

SELECT knowledge_code code,title title,status status,type objectType,confidence FROM t_knowledge_card
WHERE knowledge_base_id=#{kb} AND knowledge_code IN
#{c}

SELECT claim_code code,CONCAT_WS(' ',subject,predicate,object_value) title,status status,subject,predicate,object_value objectValue,confidence,polarity,certainty FROM t_claim
WHERE knowledge_base_id=#{kb} AND claim_code IN
#{c}

SELECT evidence_code code,LEFT(COALESCE(quote_text,''),120) title,status status,authority_score confidence FROM t_evidence
WHERE knowledge_base_id=#{kb} AND evidence_code IN
#{c}

SELECT entity_code code,canonical_name title,status status,entity_type objectType,confidence FROM t_entity
WHERE knowledge_base_id=#{kb} AND entity_code IN
#{c}

SELECT source_code code,name title,status status,source_type objectType,authority_score confidence FROM t_source
WHERE knowledge_base_id=#{kb} AND source_code IN
#{c}
